package net.civeira.phylax.features.oauth.client.infrastructure.driver.rest;

import java.util.Set;
import java.util.regex.Pattern;

import io.quarkus.security.identity.IdentityProviderManager;
import io.quarkus.security.identity.SecurityIdentity;
import io.quarkus.security.identity.request.AuthenticationRequest;
import io.quarkus.smallrye.jwt.runtime.auth.JWTAuthMechanism;
import io.quarkus.vertx.http.runtime.security.ChallengeData;
import io.quarkus.vertx.http.runtime.security.HttpAuthenticationMechanism;
import io.quarkus.vertx.http.runtime.security.HttpCredentialTransport;
import io.smallrye.mutiny.Uni;
import io.vertx.ext.web.RoutingContext;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import lombok.RequiredArgsConstructor;

/**
 * The JWT mechanism of the API, except on the DCR endpoints (V.3).
 *
 * <p>
 * Their bearer is an initial or registration access token (RFC 7591 §3, RFC 7592 §3): opaque, not a
 * JWT of the server. With proactive authentication the JWT mechanism would reject it with an empty
 * 401 before {@link ClientRegisterController} could check it, so those requests stay anonymous and
 * the controller validates the token itself.
 */
@Alternative
@Priority(1)
@ApplicationScoped
@RequiredArgsConstructor
public class RegistrationAwareJwtAuthMechanism implements HttpAuthenticationMechanism {

  /**
   * {@code /oauth/openid/{tenant}/connect} and {@code /oauth/openid/{tenant}/connect/{clientId}}.
   */
  private static final Pattern REGISTRATION =
      Pattern.compile("^/+oauth/openid/[^/]+/connect(/[^/]+)?/?$");

  private final JWTAuthMechanism delegate;

  @Override
  public Uni<SecurityIdentity> authenticate(RoutingContext context,
      IdentityProviderManager identityProviderManager) {
    return isRegistration(context) ? Uni.createFrom().optional(java.util.Optional.empty())
        : delegate.authenticate(context, identityProviderManager);
  }

  @Override
  public Uni<ChallengeData> getChallenge(RoutingContext context) {
    return delegate.getChallenge(context);
  }

  @Override
  public Set<Class<? extends AuthenticationRequest>> getCredentialTypes() {
    return delegate.getCredentialTypes();
  }

  @Override
  public Uni<HttpCredentialTransport> getCredentialTransport(RoutingContext context) {
    return delegate.getCredentialTransport(context);
  }

  static boolean isRegistration(RoutingContext context) {
    return REGISTRATION.matcher(context.normalizedPath()).matches();
  }
}
